# Essence Scatter: "Counter target creature spell."
# Word for word M20 Bone to Ash's first sentence (verified record): COUNTER_SPELL over a TARGET
# Selector on the stack, filtered to a SPELL that is a Creature. The compiler gave no tree.
abilities = [
    SpellAbility(
        kind=SpellKind.INSTANT,
        effect=A(Verb.COUNTER_SPELL, {
            'target': Selector(
                count=QConst(value=1),
                mode=SelectorMode.TARGET,
                filter=FAnd(children=(
                    FAtom(pred=FAtomPred.STACK_KIND_EQ, string_value='SPELL'),
                    FAtom(pred=FAtomPred.TYPE_EQ, string_value='Creature'),
                )),
                zones=(Zone(kind=ZoneKind.STACK, controller=ControllerRef.ANY),),
            ),
        }),
    ),
]
